// src/components/Controls.js

import React from 'react';
import { useTranslation } from 'react-i18next';
import './Controls.css';

export default function Controls({
  provinces,
  selectedProvinces,
  onChangeProvinces,
  foodTypes,
  selectedFoodType,
  onChangeFoodType,
  dateRange,
  onChangeDateRange
}) {
  const { t } = useTranslation();

  // Show loading until data arrives
  if (!foodTypes.length || !provinces.length) {
    return (
      <div style={{
        textAlign: 'center',
        padding: '40px',
        color: '#6B7280',
        fontSize: '16px'
      }}>
        Loading...
      </div>
    );
  }

  const handleProvinceToggle = prov => {
    const newSelection = selectedProvinces.includes(prov)
      ? selectedProvinces.filter(p => p !== prov)
      : [...selectedProvinces, prov];
    onChangeProvinces(newSelection);
  };

  return (
    <div style={{
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
      gap: '24px'
    }}>
      {/* Food Type Selection */}
      <div style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '8px'
      }}>
        <label htmlFor="food-type-select" style={{
          fontSize: '14px',
          fontWeight: '600',
          color: '#374151',
          marginBottom: '4px'
        }}>
          {t('select_food_type')}
        </label>
        <select
          id="food-type-select"
          value={selectedFoodType}
          onChange={e => onChangeFoodType(e.target.value)}
          style={{
            padding: '12px 16px',
            border: '1px solid #D1D5DB',
            borderRadius: '8px',
            fontSize: '16px',
            backgroundColor: 'white',
            color: '#111827',
            cursor: 'pointer',
            outline: 'none',
            transition: 'border-color 0.2s, box-shadow 0.2s'
          }}
          onFocus={(e) => {
            e.target.style.borderColor = '#3B82F6';
            e.target.style.boxShadow = '0 0 0 3px rgba(59, 130, 246, 0.1)';
          }}
          onBlur={(e) => {
            e.target.style.borderColor = '#D1D5DB';
            e.target.style.boxShadow = 'none';
          }}
        >
          <option value="" disabled>
            -- {t('select_food_type')} --
          </option>
          {foodTypes.map(type => (
            <option key={type} value={type}>
              {t(`food_types.${type}`)}
            </option>
          ))}
        </select>
      </div>

      {/* Province Selection */}
      <div style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '8px'
      }}>
        <span style={{
          fontSize: '14px',
          fontWeight: '600',
          color: '#374151',
          marginBottom: '4px'
        }}>
          {t('select_provinces')}
        </span>
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '8px'
        }}>
          {provinces.map(prov => (
            <label key={prov} style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              cursor: 'pointer',
              padding: '8px',
              borderRadius: '6px',
              transition: 'background-color 0.2s'
            }}
            onMouseEnter={(e) => e.target.style.backgroundColor = '#F3F4F6'}
            onMouseLeave={(e) => e.target.style.backgroundColor = 'transparent'}
            >
              <input
                type="checkbox"
                checked={selectedProvinces.includes(prov)}
                onChange={() => handleProvinceToggle(prov)}
                style={{
                  width: '16px',
                  height: '16px',
                  accentColor: '#3B82F6'
                }}
              />
              <span style={{
                fontSize: '16px',
                color: '#374151'
              }}>
                {prov}
              </span>
            </label>
          ))}
        </div>
      </div>

      {/* Date Range Selection */}
      <div style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '8px'
      }}>
        <label style={{
          fontSize: '14px',
          fontWeight: '600',
          color: '#374151',
          marginBottom: '4px'
        }}>
          {t('select_date_range')}
        </label>
        <div style={{
          display: 'flex',
          gap: '12px',
          alignItems: 'center'
        }}>
          <input
            type="month"
            value={dateRange.start}
            onChange={e => onChangeDateRange({ ...dateRange, start: e.target.value })}
            style={{
              padding: '12px 16px',
              border: '1px solid #D1D5DB',
              borderRadius: '8px',
              fontSize: '16px',
              backgroundColor: 'white',
              color: '#111827',
              outline: 'none',
              transition: 'border-color 0.2s, box-shadow 0.2s'
            }}
            onFocus={(e) => {
              e.target.style.borderColor = '#3B82F6';
              e.target.style.boxShadow = '0 0 0 3px rgba(59, 130, 246, 0.1)';
            }}
            onBlur={(e) => {
              e.target.style.borderColor = '#D1D5DB';
              e.target.style.boxShadow = 'none';
            }}
          />
          <span style={{
            color: '#6B7280',
            fontSize: '16px',
            fontWeight: '500'
          }}>
            –
          </span>
          <input
            type="month"
            value={dateRange.end}
            onChange={e => onChangeDateRange({ ...dateRange, end: e.target.value })}
            style={{
              padding: '12px 16px',
              border: '1px solid #D1D5DB',
              borderRadius: '8px',
              fontSize: '16px',
              backgroundColor: 'white',
              color: '#111827',
              outline: 'none',
              transition: 'border-color 0.2s, box-shadow 0.2s'
            }}
            onFocus={(e) => {
              e.target.style.borderColor = '#3B82F6';
              e.target.style.boxShadow = '0 0 0 3px rgba(59, 130, 246, 0.1)';
            }}
            onBlur={(e) => {
              e.target.style.borderColor = '#D1D5DB';
              e.target.style.boxShadow = 'none';
            }}
          />
        </div>
      </div>
    </div>
  );
}
